namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private static int _taskUiGetterUnknownCalls;
    private static void TaskUiGetterUnknownPrefix()=>_taskUiGetterUnknownCalls++;
    private sealed partial class TaskUiUnknownCardNode:NCard{}
    private sealed class TaskUiUnknownCardModel:CardModel
    {public TaskUiUnknownCardModel():base(1,CardType.Attack,CardRarity.Common,TargetType.AnyEnemy){}}
    private async Task AssertTaskUiModelGetterAsync(CombatState live,Player player)
    {
        SetStage("task_ui_model_getter");
        for(int i=0;i<3;i++)await NGame.Instance!.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
        var holders=NPlayerHand.Instance!.Holders.Where(h=>h.CardNode is not null).ToArray();
        var first=TaskUiModelGetterProof.Capture(player,holders);
        if(!first.GetterLeavesClosed||!first.CurrentModelSourcesBound||holders.Length==0)
            throw new InvalidOperationException("Ordinary UI model getters refused: "+JsonSerializer.Serialize(first));
        const BindingFlags flags=TaskUiModelGetterProof.Flags;
        FieldInfo Field(Type t,string n)=>TaskUiModelGetterProof.Field(t,n);
        var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();
        int rootHp=parent.State.GetCreature(player.Creature).CurrentHp;
        string Stamp(CombatPredictionSimulator sim)=>DescribeContinuationContractState(sim,root,player);
        string parentBefore=Stamp(parent),liveBefore=ContinuationStamp.CaptureLive(live).StateText;
        var snapshots=live.Enemies.Select(e=>CaptureActual(live,player,e)).ToArray();int getterCalls=0,helperCalls=0;
        var helperType=typeof(HealHook).Assembly.GetType("STS2RitsuLib.Scaffolding.Cards.HandOutline.Patches.ModCardHandOutlinePatchHelper",true)!;
        var helper=helperType.GetMethod("TryGetCardModel",flags)!;
        if(helper.Module.ModuleVersionId!=new Guid("f7f18a36-8ebb-4db2-b1ea-7bd340579646")||TaskUiModelGetterProof.Patched(helper))
            throw new InvalidOperationException("Unknown native UI helper binding.");
        foreach(var holder in holders)
        {
            object expectedNode=Field(typeof(NCardHolder),"<CardNode>k__BackingField").GetValue(holder)!;
            object expectedModel=Field(typeof(NCard),"_model").GetValue(expectedNode)!;
            var node=(NCard)TaskUiModelGetterProof.Getter(typeof(NCardHolder),"CardNode").Invoke(holder,null)!;
            object model=TaskUiModelGetterProof.Getter(typeof(NCard),"Model").Invoke(node,null)!;getterCalls+=2;
            if(!ReferenceEquals(node,expectedNode)||!ReferenceEquals(model,expectedModel))throw new InvalidOperationException("Native UI field getter differed.");
            object?[] args=[holder,null];if(!(bool)helper.Invoke(null,args)!||!ReferenceEquals(args[1],expectedModel))
                throw new InvalidOperationException("Observed native UI helper model differed.");
            helperCalls++;
        }
        for(int i=0;i<snapshots.Length;i++)AssertSnapshotEqual(CaptureActual(live,player,live.Enemies[i]),snapshots[i],"UiModelGetters","DirectAndHelperObservation");
        if(Stamp(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore)
            throw new InvalidOperationException("Native getters/helper changed captured state/history/RNG.");
        var cases=new List<object>();_taskUiGetterUnknownCalls=0;
        void Reject(string name,string reason,IReadOnlyList<NHandCardHolder>? input=null)
        {
            for(int i=0;i<2;i++)
            {
                var decision=TaskUiModelGetterProof.Capture(player,input??holders);
                if(decision.CurrentModelSourcesBound||!decision.Refusals.Any(s=>s.Contains(reason,StringComparison.Ordinal)))
                    throw new InvalidOperationException("Unknown UI source admitted: "+name);
                cases.Add(new{name,boundary=i==0?"prospective-root":"prospective-live",decision,productionIntegrated=false});
            }
        }
        var holder0=holders[0];var nodeField=Field(typeof(NCardHolder),"<CardNode>k__BackingField");object node0=nodeField.GetValue(holder0)!;
        var modelField=Field(typeof(NCard),"_model");object model0=modelField.GetValue(node0)!;
        Reject("unknown-holder-input","unknown-holder-instance",[null!]);
        nodeField.SetValue(holder0,null);try{Reject("null-card-node","unknown-card-node-instance");}finally{nodeField.SetValue(holder0,node0);}
        object foreignNode=RuntimeHelpers.GetUninitializedObject(typeof(TaskUiUnknownCardNode));
        nodeField.SetValue(holder0,foreignNode);try{Reject("unknown-card-node-type","unknown-card-node-instance");}finally{nodeField.SetValue(holder0,node0);}
        modelField.SetValue(node0,null);try{Reject("null-model","unknown-current-model-source");}finally{modelField.SetValue(node0,model0);}
        object foreignModel=RuntimeHelpers.GetUninitializedObject(typeof(TaskUiUnknownCardModel));
        modelField.SetValue(node0,foreignModel);try{Reject("unknown-model-type","unknown-current-model-source");}finally{modelField.SetValue(node0,model0);}
        var ownerField=Field(typeof(CardModel),"_owner");object? owner0=ownerField.GetValue(model0);
        ownerField.SetValue(model0,null);try{Reject("unknown-model-owner","unknown-current-model-owner");}finally{ownerField.SetValue(model0,owner0);}
        var harmony=new Harmony("combatsolver.testing.task-ui-model-getter");
        var prefix=typeof(UnattendedTestRunner).GetMethod(nameof(TaskUiGetterUnknownPrefix),flags)!;
        foreach(var get in new[]{TaskUiModelGetterProof.Getter(typeof(NCardHolder),"CardNode"),TaskUiModelGetterProof.Getter(typeof(NCard),"Model")})
        {
            try{harmony.Patch(get,prefix:new HarmonyMethod(prefix));Reject("unknown-getter-patch-"+get.Name,"patch:");}
            finally{harmony.Unpatch(get,HarmonyPatchType.All,harmony.Id);}
        }
        if(_taskUiGetterUnknownCalls!=0)throw new InvalidOperationException("UI source inspection invoked unknown patch.");
        var children=Enumerable.Range(0,16).Select(_=>parent.Fork()).ToArray();
        CardModel replacement=holders.Select(h=>h.CardNode!.Model!).First(m=>!ReferenceEquals(m,model0));
        modelField.SetValue(node0,replacement);
        try
        {
            await Task.WhenAll(children.Select(child=>Task.Run(()=>
            {
                using var isolation=SimulationNotificationIsolation.Enter();
                if(!first.GetterLeavesClosed||!first.CurrentModelSourcesBound||Stamp(child)!=parentBefore)
                    throw new InvalidOperationException("Frozen getter evidence changed with live source.");
                child.Damage(player.Creature,1,ValueProp.Unpowered|ValueProp.Unblockable,null);
                string after=Stamp(child);
                if(child.State.GetCreature(player.Creature).CurrentHp!=rootHp-1||Stamp(child.Fork())!=after)
                    throw new InvalidOperationException("Owned damage/Fork differed.");
            })));
        }
        finally{modelField.SetValue(node0,model0);}
        if(Stamp(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore||_taskUiGetterUnknownCalls!=0)
            throw new InvalidOperationException("Getter source branch fixture changed parent/live.");
        var restored=TaskUiModelGetterProof.Capture(player,holders);
        if(!restored.CurrentModelSourcesBound)throw new InvalidOperationException("UI model source cleanup differed.");
        var output=new{first,restored,cases,directNativeGetterCalls=getterCalls,observedNativeHelperCalls=helperCalls,
            nativeLegacySnapshotComparisons=snapshots.Length,unknownInspectionPatchCalls=_taskUiGetterUnknownCalls,
            precreatedChildren=16,ownedDamageActions=16,perChildSecondGenerationFork=1,nativeNodeQueriesReviewed=false,
            liveUiModelReferenceChangedDuringWorkers=true,
            wholeHealthCertificate=false,rootLiveProductionIntegrated=false,productionPrunes=0,searchStarted=false};
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/ui-model-getter-proof-20261008/native-details.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
        _completedChecks.Add("TaskUiModelGetters:ExactFieldLeaves:CurrentModelSources:UnknownRefusals:16OwnedDamageForks:NoWholeUiOrHealthCertificate");
    }
