using System.Collections.Immutable;
using System.Reflection;
using HarmonyLib;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Nodes.Cards;
using MegaCrit.Sts2.Core.Nodes.Cards.Holders;

namespace CombatSolver;
internal static class TaskUiModelGetterProof
{
    internal const BindingFlags Flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly;
    internal sealed record Leaf(string Getter,string Field,string Il,int MethodToken,int FieldToken);
    internal sealed record Result(bool GetterLeavesClosed,bool CurrentModelSourcesBound,ImmutableArray<string> Refusals,
        ImmutableArray<Leaf> Leaves,int Holders,int Models,bool NativeNodeQueriesReviewed=false,bool WholeHealthCertificate=false);
    internal static FieldInfo Field(Type t,string n)=>t.GetField(n,Flags)??throw new InvalidOperationException("UI getter field changed: "+n);
    internal static MethodInfo Getter(Type t,string n)=>t.GetProperty(n,Flags)?.GetMethod??throw new InvalidOperationException("UI getter changed: "+n);
    internal static bool Patched(MethodBase method)
    {var p=Harmony.GetPatchInfo(method);return p is not null&&p.Prefixes.Count+p.Postfixes.Count+p.Transpilers.Count+p.Finalizers.Count!=0;}
    internal static Result Capture(Player player,IReadOnlyList<NHandCardHolder> holders)
    {
        var reasons=ImmutableArray.CreateBuilder<string>();var leaves=ImmutableArray.CreateBuilder<Leaf>();
        var specs=new[]{(type:typeof(NCardHolder),property:"CardNode",field:"<CardNode>k__BackingField",value:typeof(NCard)),
            (type:typeof(NCard),property:"Model",field:"_model",value:typeof(CardModel))};
        foreach(var spec in specs)
        {
            MethodInfo get=Getter(spec.type,spec.property);FieldInfo field=Field(spec.type,spec.field);var body=get.GetMethodBody();var il=body?.GetILAsByteArray();
            if(get.Module.ModuleVersionId!=new Guid("8a76776c-0ce1-4d4f-90bd-8cce653dad8e")||get.IsStatic||get.IsVirtual
                ||get.GetParameters().Length!=0||get.ReturnType!=spec.value||field.IsStatic||field.FieldType!=spec.value
                ||body is null||body.LocalVariables.Count!=0||body.ExceptionHandlingClauses.Count!=0
                ||il is not [0x02,0x7b,_,_,_,_,0x2a]||get.Module.ResolveField(BitConverter.ToInt32(il,2))!=field)
                reasons.Add("unknown-getter-body:"+spec.type.Name+"."+spec.property);
            if(Patched(get))reasons.Add("patch:"+spec.type.Name+"."+spec.property);
            leaves.Add(new(get.DeclaringType!.FullName+"."+get.Name,field.Name,Convert.ToHexString(il??[]),get.MetadataToken,field.MetadataToken));
        }
        if(reasons.Count!=0)return new(false,false,reasons.ToImmutable(),leaves.ToImmutable(),holders.Count,0);
        int models=0;
        foreach(var holder in holders)
        {
            if(holder is null||holder.GetType()!=typeof(NHandCardHolder)){reasons.Add("unknown-holder-instance");continue;}
            object? node=Field(typeof(NCardHolder),"<CardNode>k__BackingField").GetValue(holder);
            if(node is null||node.GetType()!=typeof(NCard)){reasons.Add("unknown-card-node-instance");continue;}
            object? value=Field(typeof(NCard),"_model").GetValue(node);
            if(value is not CardModel card||card.GetType().Module.ModuleVersionId!=typeof(CardModel).Module.ModuleVersionId)
                {reasons.Add("unknown-current-model-source");continue;}
            if(!ReferenceEquals(Field(typeof(CardModel),"_owner").GetValue(card),player))
                {reasons.Add("unknown-current-model-owner");continue;}
            models++;
        }
        return new(true,reasons.Count==0,reasons.ToImmutable(),leaves.ToImmutable(),holders.Count,models);
    }
}

